//! Helpers for the statically translated VU1 micro code (crates t5-vu-*, generated by
//! tools/vuc.py): the same operations as `vu::upper_sse_f` / `vu::upper_int` / `vu::lower_op`, on
//! values instead of the register file. VF registers are SSE vectors (`V`, lane 0 = x), so a
//! translated block keeps them in xmm registers. Where the exact (f64) path is needed the
//! helpers fall back to it themselves (`fmac`) or return None (the translated code then calls
//! `upper_vals`).

use crate::vu::VuRegs;
use crate::Machine;
use ee_core::VI_STATUS;
use std::arch::x86_64::*;

/// A VF register: x, y, z, w in lanes 0..3.
pub type V = __m128i;

/// VU1 data memory: 1024 qwords.
const QMASK: u32 = 0x3FF;

/// vf0 = (0, 0, 0, 1.0)
pub const VF0: [u32; 4] = [0, 0, 0, 0x3F80_0000];

#[inline(always)]
pub fn vf0() -> V {
    ld(&VF0)
}

#[inline(always)]
pub fn ld(a: &[u32; 4]) -> V {
    unsafe { _mm_loadu_si128(a.as_ptr() as *const __m128i) }
}

#[inline(always)]
pub fn st(a: &mut [u32; 4], v: V) {
    unsafe { _mm_storeu_si128(a.as_mut_ptr() as *mut __m128i, v) }
}

#[inline(always)]
pub fn arr(v: V) -> [u32; 4] {
    let mut a = [0u32; 4];
    st(&mut a, v);
    a
}

#[inline(always)]
pub fn splat(x: u32) -> V {
    unsafe { _mm_set1_epi32(x as i32) }
}

/// Field `K` (0 = x .. 3 = w).
#[inline(always)]
pub fn lane<const K: i32>(v: V) -> u32 {
    unsafe { _mm_extract_epi32::<K>(v) as u32 }
}

/// Field `K` in all four.
#[inline(always)]
pub fn bcast<const K: i32>(v: V) -> V {
    unsafe {
        match K {
            0 => _mm_shuffle_epi32::<0x00>(v),
            1 => _mm_shuffle_epi32::<0x55>(v),
            2 => _mm_shuffle_epi32::<0xAA>(v),
            _ => _mm_shuffle_epi32::<0xFF>(v),
        }
    }
}

/// MR32: (y, z, w, x)
#[inline(always)]
pub fn mr32(v: V) -> V {
    unsafe { _mm_shuffle_epi32::<0b00_11_10_01>(v) }
}

/// The fields `D` (x = 8 .. w = 1) of `new`, the rest of `old`.
#[inline(always)]
pub fn blend<const D: u32>(old: V, new: V) -> V {
    blend_d(old, new, D)
}

/// `blend` with the mask as an argument (a constant after inlining).
#[inline(always)]
fn blend_d(old: V, new: V, d: u32) -> V {
    unsafe {
        let o = _mm_castsi128_ps(old);
        let n = _mm_castsi128_ps(new);
        let r = match d & 0xF {
            0x0 => o,
            0x1 => _mm_blend_ps::<0b1000>(o, n),
            0x2 => _mm_blend_ps::<0b0100>(o, n),
            0x3 => _mm_blend_ps::<0b1100>(o, n),
            0x4 => _mm_blend_ps::<0b0010>(o, n),
            0x5 => _mm_blend_ps::<0b1010>(o, n),
            0x6 => _mm_blend_ps::<0b0110>(o, n),
            0x7 => _mm_blend_ps::<0b1110>(o, n),
            0x8 => _mm_blend_ps::<0b0001>(o, n),
            0x9 => _mm_blend_ps::<0b1001>(o, n),
            0xA => _mm_blend_ps::<0b0101>(o, n),
            0xB => _mm_blend_ps::<0b1101>(o, n),
            0xC => _mm_blend_ps::<0b0011>(o, n),
            0xD => _mm_blend_ps::<0b1011>(o, n),
            0xE => _mm_blend_ps::<0b0111>(o, n),
            _ => n,
        };
        _mm_castps_si128(r)
    }
}

/// Lane bits (lane 0 = bit 0) of a dest mask (x = 8 .. w = 1).
#[inline(always)]
const fn lanebits(d: u32) -> i32 {
    (((d >> 3) & 1) | ((d >> 2) & 1) << 1 | ((d >> 1) & 1) << 2 | (d & 1) << 3) as i32
}

/// Read the qword at `a` (masked: always inside data memory).
#[inline(always)]
pub fn rq(data: *mut u8, a: u32) -> V {
    unsafe { _mm_loadu_si128(data.add(((a & QMASK) as usize) * 16) as *const __m128i) }
}

/// Write the fields `D` of the qword at `a`.
#[inline(always)]
pub fn wq<const D: u32>(data: *mut u8, a: u32, v: V) {
    let p = unsafe { data.add(((a & QMASK) as usize) * 16) };
    if D & 0xF == 0xF {
        unsafe { _mm_storeu_si128(p as *mut __m128i, v) };
        return;
    }
    let x = arr(v);
    for k in 0..4 {
        if D & (8 >> k) != 0 {
            unsafe { std::ptr::write_unaligned(p.add(4 * k) as *mut u32, x[k]) };
        }
    }
}

/// Lanes (lane bits) whose biased exponent is >= `e`.
#[inline(always)]
fn exp_ge(x: V, e: u32) -> i32 {
    unsafe {
        let ex = _mm_and_si128(x, _mm_set1_epi32(0x7F80_0000));
        _mm_movemask_ps(_mm_castsi128_ps(_mm_cmpgt_epi32(ex, _mm_set1_epi32(((e << 23) - 1) as i32))))
    }
}

/// Lanes (lane bits) with exponent 0.
#[inline(always)]
fn exp_zero(x: V) -> i32 {
    unsafe {
        let ex = _mm_and_si128(x, _mm_set1_epi32(0x7F80_0000));
        _mm_movemask_ps(_mm_castsi128_ps(_mm_cmpeq_epi32(ex, _mm_setzero_si128())))
    }
}

/// MAC sign bits (x = bit 7 .. w = bit 4) from lane sign bits (lane 0 = bit 0).
const SIGNS: [u32; 16] = {
    let mut t = [0u32; 16];
    let mut i = 0;
    while i < 16 {
        let mut m = 0;
        let mut k = 0;
        while k < 4 {
            if i & (1 << k) != 0 {
                m |= 1 << (3 - k + 4);
            }
            k += 1;
        }
        t[i] = m;
        i += 1;
    }
    t
};

/// MAC zero bits (x = bit 3 .. w = bit 0) from lane bits (lane 0 = bit 0).
const ZEROS: [u32; 16] = {
    let mut t = [0u32; 16];
    let mut i = 0;
    while i < 16 {
        let mut m = 0;
        let mut k = 0;
        while k < 4 {
            if i & (1 << k) != 0 {
                m |= 1 << (3 - k);
            }
            k += 1;
        }
        t[i] = m;
        i += 1;
    }
    t
};

/// Lanes (lane bits) whose exact result is zero (so an exponent-0 result there is that zero,
/// not an underflow): a product with a zero operand (exponent 0 counts as zero, as DAZ treats
/// it), a sum of two numbers equal in magnitude and opposite in sign (or two zeros). The
/// product inside MADD / MSUB is the single-rounded one the FMAC adds, as in ee_core::vu0.
#[inline(always)]
fn exact_zero_lanes(kind: u32, a: __m128, b: __m128, c: __m128) -> i32 {
    unsafe {
        let neg = |x: __m128| _mm_xor_ps(x, _mm_set1_ps(-0.0));
        let zero = |x: __m128| exp_zero(_mm_castps_si128(x));
        match kind {
            2 | 5 => zero(a) | zero(b),
            0 => _mm_movemask_ps(_mm_cmpeq_ps(a, neg(b))),
            1 => _mm_movemask_ps(_mm_cmpeq_ps(a, b)),
            3 => _mm_movemask_ps(_mm_cmpeq_ps(c, neg(_mm_mul_ps(a, b)))),
            _ => _mm_movemask_ps(_mm_cmpeq_ps(c, _mm_mul_ps(a, b))),
        }
    }
}

/// Status from a new MAC value (ee_core::vu0::set_mac).
#[inline(always)]
fn status_of(mac: u32, st: u32) -> u32 {
    let mut s2 = st & 0xFF0 & !0x0F;
    if mac & 0x000F != 0 {
        s2 |= 1;
    }
    if mac & 0x00F0 != 0 {
        s2 |= 2;
    }
    if mac & 0x0F00 != 0 {
        s2 |= 4;
    }
    if mac & 0xF000 != 0 {
        s2 |= 8;
    }
    s2 |= (s2 & 0xF) << 6;
    s2 | (st & 0x30)
}

/// The kind of FMAC upper word `w`: 0 add, 1 sub, 2 mul, 3 madd, 4 msub, 5 opmula, 6 opmsub.
#[inline(always)]
const fn fmac_kind(w: u32) -> Option<u32> {
    let funct = w & 0x3F;
    let special = funct >= 0x3C;
    let code = if special { (funct & 3) | ((w >> 6) & 31) << 2 } else { funct };
    Some(match code {
        0x00..=0x03 | 0x20 | 0x22 | 0x28 => 0,
        0x04..=0x07 | 0x24 | 0x26 | 0x2C => 1,
        0x18..=0x1B | 0x1C | 0x1E | 0x2A => 2,
        0x08..=0x0B | 0x21 | 0x23 | 0x29 => 3,
        0x0C..=0x0F | 0x25 | 0x27 | 0x2D => 4,
        0x2E => {
            if special {
                5
            } else {
                6
            }
        }
        _ => return None,
    })
}

/// An FMAC operation (upper word `W`): (destination after the write, MAC, Status), or None for
/// the exact path. `dst` is ACC or vf[fd]; `t` is the second operand already selected (bc
/// broadcast, Q, I, or ft); `st` the Status register the operation starts from. As
/// `vu::upper_sse_f`: operands of the written lanes below 2^63; with `FLAGS`, written lanes with
/// exponent 0 (zero / underflow) are recomputed exactly here for their MAC bits.
#[inline(always)]
pub fn fmac<const W: u32, const FLAGS: bool>(s: V, t: V, acc: V, dst: V, st: u32) -> Option<(V, u32, u32)> {
    let kind = fmac_kind(W)?;
    let dmask = (W >> 21) & 0xF;
    if FLAGS && dmask == 0 {
        return None;
    }
    unsafe {
        // OPMULA / OPMSUB: fs.yzx * ft.zxy into xyz.
        let (s, t, lanes) = if kind >= 5 {
            (_mm_shuffle_epi32::<0b11_00_10_01>(s), _mm_shuffle_epi32::<0b11_01_00_10>(t), 0xE)
        } else {
            (s, t, dmask)
        };
        let lb = lanebits(lanes);
        let uses_acc = matches!(kind, 3 | 4 | 6);
        let mut big = exp_ge(s, 0xBE) | exp_ge(t, 0xBE);
        if uses_acc {
            big |= exp_ge(acc, 0xBE);
        }
        if big & lb != 0 {
            return None;
        }
        let (a, b, c) = (_mm_castsi128_ps(s), _mm_castsi128_ps(t), _mm_castsi128_ps(acc));
        let r = match kind {
            0 => _mm_add_ps(a, b),
            1 => _mm_sub_ps(a, b),
            2 | 5 => _mm_mul_ps(a, b),
            3 => _mm_add_ps(c, _mm_mul_ps(a, b)),
            _ => _mm_sub_ps(c, _mm_mul_ps(a, b)),
        };
        let mut out = _mm_castps_si128(r);
        let (mut mac, mut status) = (0, st);
        if FLAGS {
            let zl = exp_zero(out) & lb;
            if zl != 0 && zl & !exact_zero_lanes(kind, a, b, c) != 0 {
                (out, mac) = fmac_exact(kind, lanes, s, t, acc, out);
            } else if zl != 0 {
                // Every zero lane is an exact zero (no underflow): zero bits plus signs.
                mac = SIGNS[(_mm_movemask_ps(_mm_castsi128_ps(out)) & lb) as usize] | ZEROS[zl as usize];
            } else {
                mac = SIGNS[(_mm_movemask_ps(_mm_castsi128_ps(out)) & lb) as usize];
            }
            status = status_of(mac, st);
        }
        let d = blend_d(dst, out, lanes);
        Some((d, mac, status))
    }
}

/// The written lanes of an FMAC result with a zero / underflowed lane as ee_core::vu0 computes
/// them (f64, products rounded to EE singles before accumulation), with their MAC bits.
#[cold]
#[inline(never)]
fn fmac_exact(kind: u32, lanes: u32, s: V, t: V, acc: V, out: V) -> (V, u32) {
    let f = ee_core::fpu::ps2_to_f64;
    let r = ee_core::fpu::f64_to_ps2;
    let rr = |x: f64| f(r(x));
    let (sa, ta, ca) = (arr(s), arr(t), arr(acc));
    let mut o = arr(out);
    let mut mac = 0;
    for k in 0..4 {
        if lanes & (8 >> k) == 0 {
            continue;
        }
        let x = match kind {
            0 => f(sa[k]) + f(ta[k]),
            1 => f(sa[k]) - f(ta[k]),
            2 | 5 => f(sa[k]) * f(ta[k]),
            3 => f(ca[k]) + rr(f(sa[k]) * f(ta[k])),
            _ => f(ca[k]) - rr(f(sa[k]) * f(ta[k])),
        };
        let bits = r(x);
        o[k] = bits;
        let bit = 3 - k;
        if bits & 0x7FFF_FFFF == 0 {
            mac |= 1 << bit;
            if x != 0.0 && (x.to_bits() >> 52) & 0x7FF != 0 {
                mac |= 1 << (bit + 8);
            }
        }
        if bits & 0x8000_0000 != 0 {
            mac |= 1 << (bit + 4);
        }
        if bits & 0x7FFF_FFFF == 0x7FFF_FFFF && x.abs() > 6.805646932770577e38 {
            mac |= 1 << (bit + 12);
        }
    }
    (ld(&o), mac)
}

/// Sign-magnitude order as two's complement order.
#[inline(always)]
fn smkey(x: V) -> V {
    unsafe { _mm_xor_si128(x, _mm_and_si128(_mm_srai_epi32::<31>(x), _mm_set1_epi32(0x7FFF_FFFF))) }
}

/// MAX / MINI (sign-magnitude compare) into the fields `D` of `dst`.
#[inline(always)]
pub fn minmax<const D: u32, const MAX: bool>(dst: V, s: V, t: V) -> V {
    unsafe {
        // s where (key(s) >= key(t)) == MAX, else t
        let lt = _mm_cmpgt_epi32(smkey(t), smkey(s)); // key(s) < key(t)
        let pick_t = if MAX { lt } else { _mm_xor_si128(lt, _mm_set1_epi32(-1)) };
        let r = _mm_castps_si128(_mm_blendv_ps(_mm_castsi128_ps(s), _mm_castsi128_ps(t), _mm_castsi128_ps(pick_t)));
        blend::<D>(dst, r)
    }
}

/// ABS
#[inline(always)]
pub fn abs<const D: u32>(dst: V, s: V) -> V {
    unsafe { blend::<D>(dst, _mm_and_si128(s, _mm_set1_epi32(0x7FFF_FFFF))) }
}

/// ITOF0/4/12/15 (`SH` = 0, 4, 12, 15): exact with MXCSR round toward zero (set for VU1 runs).
#[inline(always)]
pub fn itof<const D: u32, const SH: u32>(dst: V, s: V) -> V {
    unsafe {
        let x = _mm_cvtepi32_ps(s);
        let r = _mm_mul_ps(x, _mm_set1_ps(1.0 / (1u32 << SH) as f32));
        blend::<D>(dst, _mm_castps_si128(r))
    }
}

/// FTOI0/4/12/15; None when a written field needs saturation (exact path).
#[inline(always)]
pub fn ftoi<const D: u32, const SH: u32>(dst: V, s: V) -> Option<V> {
    if exp_ge(s, 0x9E - SH) & lanebits(D) != 0 {
        return None;
    }
    unsafe {
        let r = _mm_cvttps_epi32(_mm_mul_ps(_mm_castsi128_ps(s), _mm_set1_ps((1u32 << SH) as f32)));
        Some(blend::<D>(dst, r))
    }
}

/// CLIPw.xyz: the new clip register, or None (an operand with exponent 255: exact path).
#[inline(always)]
pub fn clip(s: V, w: u32, clip: u32) -> Option<u32> {
    if (w >> 23) & 0xFF == 0xFF || exp_ge(s, 0xFF) & 0b0111 != 0 {
        return None;
    }
    let s = arr(s);
    let fl = |x: u32| if (x >> 23) & 0xFF == 0 { 0.0f32 } else { f32::from_bits(x) };
    let wv = fl(w).abs();
    let mut flags = 0u32;
    for k in 0..3 {
        let x = fl(s[k]);
        if x > wv {
            flags |= 1 << (2 * k);
        }
        if x < -wv {
            flags |= 1 << (2 * k + 1);
        }
    }
    Some(((clip << 6) | flags) & 0xFF_FFFF)
}

/// What an upper instruction leaves (exact path): vf[ft], vf[fd], ACC, MAC, Status, Clip.
pub struct UpOut {
    pub ft: V,
    pub fd: V,
    pub acc: V,
    pub mac: u32,
    pub status: u32,
    pub clip: u32,
}

/// An upper instruction exactly (ee_core::vu0::upper_ex) on values: `W` is the word with fs =
/// vf1, ft = vf2 and, for the non-ACC forms, fd = vf3 (tools/vuc.py renumbers them); `s`, `t`,
/// `fd` are the operand registers' values, `mac` / `status` / `clip` the flags the FMAC units
/// compute from (as `vu::pair_body` sets them).
#[cold]
#[inline(never)]
#[allow(clippy::too_many_arguments)]
pub fn upper_vals<const W: u32, const FLAGS: bool>(s: V, t: V, fd: V, acc: V, q: u32, i: u32, mac: u32, status: u32, clip: u32) -> UpOut {
    let mut r: VuRegs = unsafe { std::mem::zeroed() };
    r.vf[0] = VF0;
    r.vf[1] = arr(s);
    r.vf[2] = arr(t);
    r.vf[3] = arr(fd);
    r.acc = arr(acc);
    r.vi[ee_core::VI_Q] = q;
    r.vi[ee_core::VI_I] = i;
    r.vi[ee_core::VI_MAC] = mac;
    r.vi[VI_STATUS] = status;
    r.vi[ee_core::VI_CLIP] = clip;
    ee_core::vu0::upper_ex::<FLAGS>(&mut r, W & 0x01FF_FFFF);
    UpOut { ft: ld(&r.vf[2]), fd: ld(&r.vf[3]), acc: ld(&r.acc), mac: r.vi[ee_core::VI_MAC], status: r.vi[VI_STATUS], clip: r.vi[ee_core::VI_CLIP] }
}

/// DIV / SQRT / RSQRT (`op` 0..2) of fs.fsf `a` and ft.ftf `b`: (Q, Status) the FDIV unit
/// delivers (as ee_core::vu0::fdiv).
#[inline(always)]
pub fn fdiv(op: u32, a: u32, b: u32, status: u32) -> (u32, u32) {
    let f = ee_core::fpu::ps2_to_f64;
    let r = ee_core::fpu::f64_to_ps2;
    let mut st = status & !0x30;
    let res = match op {
        0 => {
            if b & 0x7FFF_FFFF == 0 {
                if a & 0x7FFF_FFFF == 0 {
                    st |= 0x10 | 0x400;
                } else {
                    st |= 0x20 | 0x800;
                }
                ((a ^ b) & 0x8000_0000) | 0x7FFF_FFFF
            } else {
                r(f(a) / f(b))
            }
        }
        1 => {
            if b & 0x8000_0000 != 0 && b & 0x7FFF_FFFF != 0 {
                st |= 0x10 | 0x400;
            }
            r(f(b).abs().sqrt())
        }
        _ => {
            if b & 0x7FFF_FFFF == 0 {
                st |= 0x20 | 0x800;
                (a & 0x8000_0000) | 0x7FFF_FFFF
            } else {
                if b & 0x8000_0000 != 0 {
                    st |= 0x10 | 0x400;
                }
                r(f(a) / f(b).abs().sqrt())
            }
        }
    };
    (res, st)
}

/// The EFU operations (`op` 0x70..0x7E) on fs: P.
#[inline(never)]
pub fn efu(op: u32, s: V, fsf: usize) -> u32 {
    let s = arr(s);
    let f = ee_core::fpu::ps2_to_f64;
    let tof = ee_core::fpu::f64_to_ps2;
    tof(match op {
        0x70 => f(s[0]) * f(s[0]) + f(s[1]) * f(s[1]) + f(s[2]) * f(s[2]),
        0x71 => 1.0 / (f(s[0]) * f(s[0]) + f(s[1]) * f(s[1]) + f(s[2]) * f(s[2])),
        0x72 => (f(s[0]) * f(s[0]) + f(s[1]) * f(s[1]) + f(s[2]) * f(s[2])).sqrt(),
        0x73 => 1.0 / (f(s[0]) * f(s[0]) + f(s[1]) * f(s[1]) + f(s[2]) * f(s[2])).sqrt(),
        0x74 => f(s[1]).atan2(f(s[0])),
        0x75 => f(s[2]).atan2(f(s[0])),
        0x76 => f(s[0]) + f(s[1]) + f(s[2]) + f(s[3]),
        0x78 => f(s[fsf]).abs().sqrt(),
        0x79 => 1.0 / f(s[fsf]).abs().sqrt(),
        0x7A => 1.0 / f(s[fsf]),
        0x7C => f(s[fsf]).sin(),
        0x7D => f(s[fsf]).atan(),
        _ => (-f(s[fsf])).exp(),
    })
}

/// RNEXT: the next R.
#[inline(always)]
pub fn rnext(r: u32) -> u32 {
    let x = r & 0x7F_FFFF;
    let bit = ((x >> 4) ^ (x >> 22)) & 1;
    0x3F80_0000 | ((x << 1 | bit) & 0x7F_FFFF)
}

/// XTOP / XITOP (VU1).
#[inline(always)]
pub fn xtop(mp: *mut Machine) -> u32 {
    unsafe { (*mp).vif[1].top }
}

#[inline(always)]
pub fn xitop(mp: *mut Machine) -> u32 {
    unsafe { (*mp).vif[1].itop }
}

/// XGKICK: PATH1 from data memory at `addr` (it reads data memory and the GIF / GS state only).
#[inline(never)]
pub fn xgkick(mp: *mut Machine, data: *mut u8, addr: u32) {
    crate::vu::xgkick(mp, data, addr);
}
